#!/bin/bash
# ============================================================
# 4_4_run_t2d_prs.sh — Compute T2D PRS on the full UKB sample
#
# Weight source: t2d_score_<id>.txt generated by 4_4_build_t2d_prs.R
#   (SNP effect_allele beta)
#
# Workflow (fixed version):
#   1. PLINK2 --export A exports weighted SNP dosages chromosome by chromosome
#   2. Allele check (flip to 2-dosage if not matching the score file effect allele) + beta-weighted sum
#      (fix: the old version mistakenly used the unweighted .sscore column NAMED_ALLELE_DOSAGE_SUM)
#
# Usage: bash code/03_genetics/4_4_run_t2d_prs.sh
# ============================================================
# ── paths (override via env: PANCREASAGE_DATA / PANCREASAGE_OUT / PLINK2 / REGENIE) ──
PKG_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
DATA_ROOT="${PANCREASAGE_DATA:-${PKG_ROOT}/data}"
OUT_ROOT="${PANCREASAGE_OUT:-${PKG_ROOT}/results}"
set -e

PLINK2="${PLINK2:-plink2}"
THREADS=16

PGEN_DIR="${PGEN_DIR:-${DATA_ROOT}/genotypes/pgen}"
RES_ROOT="${RES_ROOT:-${OUT_ROOT}}"
PRS_DIR="$RES_ROOT/prs_analysis"
OUT_DIR="$PRS_DIR/t2d_prs_build"
KEEP_ALL="$PRS_DIR/keep_all.id"

mkdir -p "$OUT_DIR"
echo "Keep all samples: $(wc -l < $KEEP_ALL)"

SCORES=(
    "ieu-a-23:$PRS_DIR/t2d_score_ieu-a-23.txt"
    "finn-b-T2D:$PRS_DIR/t2d_score_finn-b-T2D.txt"
)

for entry in "${SCORES[@]}"; do
    OID="${entry%%:*}"
    SCORE_FILE="${entry#*:}"
    echo ""
    echo "========================================="
    echo " T2D PRS: ${OID}"
    echo "========================================="

    # Build SNP list from the score file
    SNP_LIST="$OUT_DIR/t2d_${OID}_snplist.txt"
    cut -f1 "$SCORE_FILE" | sort -u > "$SNP_LIST"
    echo "  Weight SNPs: $(wc -l < $SNP_LIST)"

    # Export dosages chromosome by chromosome
    for CHR in $(seq 1 22); do
        RAW_OUT="$OUT_DIR/t2d_${OID}_chr${CHR}"
        if [ -f "${RAW_OUT}.raw" ]; then
            continue
        fi
        $PLINK2 --pfile "${PGEN_DIR}/ukb22828_c${CHR}_b0_v3" \
            --keep "$KEEP_ALL" \
            --extract "$SNP_LIST" \
            --export A \
            --out "$RAW_OUT" \
            --threads $THREADS \
            --silent || true
        if [ ! -f "${RAW_OUT}.raw" ]; then
            rm -f "${RAW_OUT}.log" "${RAW_OUT}.nosex"
        fi
    done

    # Python merge: allele check + beta weighting
    python3 -c "
import os
import pandas as pd
import numpy as np

PRS_DIR = '$PRS_DIR'
OUT_DIR = '$OUT_DIR'
OID = '$OID'

score_file = os.path.join(PRS_DIR, f't2d_score_{OID}.txt')
scores = pd.read_csv(score_file, sep='\t', header=None, names=['SNP', 'ALLELE', 'BETA'])
scores['ALLELE'] = scores['ALLELE'].astype(str).str.upper()
beta_map = dict(zip(scores['SNP'].astype(str), scores['BETA'].astype(float)))
a1_map = dict(zip(scores['SNP'].astype(str), scores['ALLELE']))

total = None
for chr_num in range(1, 23):
    raw = os.path.join(OUT_DIR, f't2d_{OID}_chr{chr_num}.raw')
    if not os.path.exists(raw):
        continue
    df = pd.read_csv(raw, sep=r'\s+')
    score = np.zeros(len(df))
    snp_cols = [c for c in df.columns
                if c not in ('FID', 'IID', 'PAT', 'MAT', 'SEX', 'PHENOTYPE')
                and not c.endswith('_HET')]
    for col in snp_cols:
        sid, _, counted = col.partition('_')
        counted = counted.upper()
        a1 = a1_map.get(sid)
        dos = pd.to_numeric(df[col], errors='coerce').fillna(0).values
        if a1 is not None and counted and counted != a1:
            dos = 2.0 - dos
        score += dos * beta_map.get(sid, 0.0)
    out = df[['FID', 'IID']].copy()
    out['score'] = score
    if total is None:
        total = out
    else:
        assert (total['IID'].values == out['IID'].values).all(), f'chr{chr_num} sample order mismatch'
        total['score'] += out['score'].values

label = f'T2D_PRS_{OID}'
total = total.rename(columns={'score': label})
total.to_csv(os.path.join(PRS_DIR, f'{label}_raw.csv'), index=False)
print(f'  [{label}] {len(total)} samples → {PRS_DIR}/{label}_raw.csv')
"
done

echo ""
echo "========================================="
echo " T2D PRS scoring complete!"
echo "========================================="
